  id: 'l28-4', moduleNum: 12, lessonNum: 4, moduleTitle: 'Emotions & Feelings', type: 'grammar', title: 'Verbs + -ing: enjoy, love, hate, finish, mind, avoid', xp: 70, duration: 65,
  paragraphs: [], dialogue: [], keyPhrases: [], vocab: [], prepTasks: [], task1Bank: [], task1Items: [], task2Items: [],
  listenChars: [], listenStatements: [],
